<?php
namespace Tests\Feature;
use App\Models\User;
use Database\Seeders\DatabaseSeeder;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Tests\TestCase;
class SchoolFinanceTest extends TestCase {
 use RefreshDatabase;
 protected function beforeRefreshingDatabase():void{if(!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Dedicated test database required.');}
 protected function setUp():void{parent::setUp();\Carbon\Carbon::setTestNow('2026-10-19 08:00:00');}
 protected function tearDown():void{\Carbon\Carbon::setTestNow();parent::tearDown();}
 private function fixture(string $code='F'):array{if(!DB::table('roles')->exists())$this->seed(DatabaseSeeder::class);$sid=DB::table('schools')->insertGetId(['name'=>'Finance '.$code,'code'=>$code,'status'=>'active','timezone'=>'Asia/Karachi','currency'=>'PKR']);$campus=DB::table('campuses')->insertGetId(['school_id'=>$sid,'name'=>'Main','code'=>'MAIN','status'=>'active']);$owner=User::factory()->create();$mid=DB::table('school_memberships')->insertGetId(['school_id'=>$sid,'user_id'=>$owner->id,'status'=>'active']);DB::table('membership_roles')->insert(['school_id'=>$sid,'membership_id'=>$mid,'role_id'=>DB::table('roles')->where('name','owner')->value('id')]);DB::table('membership_campuses')->insert(['school_id'=>$sid,'membership_id'=>$mid,'campus_id'=>$campus]);$category=DB::table('expense_categories')->insertGetId(['school_id'=>$sid,'name'=>'Utilities','code'=>'UTIL']);$bank=DB::table('bank_accounts')->insertGetId(['school_id'=>$sid,'campus_id'=>$campus,'name'=>'Bank','opening_balance'=>'0']);return compact('sid','campus','owner','mid','category','bank');}
 private function login(array $f):void{$this->actingAs($f['owner'])->withSession(['school_id'=>$f['sid']]);}
 private function data(array $f):array{return ['campus_id'=>$f['campus'],'category_id'=>$f['category'],'amount'=>'1000','incurred_on'=>'2026-10-17','payee'=>'Utility supplier','description'=>'School utility bill','method'=>'cash','bank_account_id'=>null,'reference'=>null,'entry_key'=>(string)Str::uuid()];}
 private function expense(array $f,bool $pay=false):int{$id=$this->postJson('/app-api/finance/expenses',$this->data($f))->assertOk()->json('id');$this->postJson('/app-api/finance/expenses/'.$id.'/action',['action'=>'approve','lock_version'=>0,'reason'=>'Checked original utility invoice'])->assertOk();if($pay)$this->postJson('/app-api/finance/expenses/'.$id.'/action',['action'=>'pay','lock_version'=>1,'paid_on'=>'2026-10-18','payment_key'=>(string)Str::uuid()])->assertOk();return $id;}
 private function report(array $f,string $from='2026-10-17',string $to='2026-10-19'){return $this->getJson('/app-api/finance/report?campus_id='.$f['campus'].'&from='.$from.'&to='.$to);}
 private function closing(array $f,string $day='2026-10-18',string $count='4000'):int{$d=['campus_id'=>$f['campus'],'bank_account_id'=>null,'closing_date'=>$day,'opening_balance'=>'5000'];$p=$this->postJson('/app-api/finance/closing-preview',$d)->assertOk()->json();return $this->postJson('/app-api/finance/closings',$d+['counted_balance'=>$count,'source_digest'=>$p['source_digest'],'reason'=>'Verified cash count and opening float'])->assertOk()->json('id');}
 public function test_expenses_require_review_and_separate_payment_and_retries_never_duplicate():void{$f=$this->fixture();$this->login($f);$d=$this->data($f);$id=$this->postJson('/app-api/finance/expenses',$d)->assertOk()->json('id');$this->postJson('/app-api/finance/expenses',$d)->assertOk()->assertJsonPath('id',$id);$this->postJson('/app-api/finance/expenses',array_replace($d,['amount'=>'1001']))->assertUnprocessable();$pay=['action'=>'pay','lock_version'=>0,'paid_on'=>'2026-10-18','payment_key'=>(string)Str::uuid()];$this->postJson('/app-api/finance/expenses/'.$id.'/action',$pay)->assertUnprocessable();$this->postJson('/app-api/finance/expenses/'.$id.'/action',['action'=>'approve','lock_version'=>0,'reason'=>'Reviewed supplier invoice'])->assertOk();$this->report($f)->assertJsonPath('totals.outflow','0.00');$pay['lock_version']=1;$this->postJson('/app-api/finance/expenses/'.$id.'/action',$pay)->assertOk();$this->postJson('/app-api/finance/expenses/'.$id.'/action',$pay)->assertOk();$this->report($f)->assertJsonPath('totals.outflow','1000.00')->assertJsonPath('totals.book_net','-1000.00');$this->assertDatabaseCount('expenses',1);$this->getJson('/app-api/finance/expenses/'.$id)->assertJsonPath('expense.snapshot.payee','Utility supplier');$this->artisan('database:verify')->assertSuccessful();}
 public function test_partial_refund_is_actual_inflow_but_full_correction_is_separate_and_original_receipt_survives():void{$f=$this->fixture();$this->login($f);$id=$this->expense($f,true);$d=['kind'=>'refund','amount'=>'300','method'=>'cash','bank_account_id'=>null,'effective_on'=>'2026-10-19','reason'=>'Returned unused supplies','entry_key'=>(string)Str::uuid()];$v=$this->postJson('/app-api/finance/expenses/'.$id.'/reversals',$d)->assertOk()->json('id');$this->postJson('/app-api/finance/reversals/'.$v.'/review',['action'=>'approve','reason'=>'Verified returned cash'])->assertOk();$this->report($f)->assertJsonPath('totals.inflow','300.00')->assertJsonPath('totals.outflow','1000.00')->assertJsonPath('totals.corrections','0.00')->assertJsonPath('totals.book_net','-700.00');$d['amount']='701';$d['entry_key']=(string)Str::uuid();$this->postJson('/app-api/finance/expenses/'.$id.'/reversals',$d)->assertUnprocessable();$id2=$this->expense($f,true);$d=array_replace($d,['kind'=>'correction','amount'=>'1000','entry_key'=>(string)Str::uuid()]);$v=$this->postJson('/app-api/finance/expenses/'.$id2.'/reversals',$d)->assertOk()->json('id');$this->postJson('/app-api/finance/reversals/'.$v.'/review',['action'=>'approve','reason'=>'Incorrect duplicate bookkeeping'])->assertOk();$this->report($f)->assertJsonPath('totals.inflow','300.00')->assertJsonPath('totals.outflow','2000.00')->assertJsonPath('totals.corrections','1000.00')->assertJsonPath('totals.book_net','-700.00');$this->getJson('/app-api/finance/expenses/'.$id2)->assertJsonPath('expense.snapshot.amount','1000.00');}
 public function test_closing_preview_staleness_immutable_approval_and_backdated_changes_are_detected():void{$f=$this->fixture();$this->login($f);$this->expense($f,true);$id=$this->closing($f);$this->postJson('/app-api/finance/closings/'.$id.'/review',['action'=>'approve','reason'=>'Cash counted and verified'])->assertOk();$this->getJson('/app-api/finance/closings/'.$id)->assertJsonPath('source_changed',false)->assertJsonPath('closing.expected_balance','4000.00');$this->expense($f,true);$this->getJson('/app-api/finance/closings/'.$id)->assertJsonPath('source_changed',true)->assertJsonPath('closing.expected_balance','4000.00');$id2=$this->closing($f,'2026-10-18','3000');$this->postJson('/app-api/finance/closings/'.$id2.'/review',['action'=>'approve','reason'=>'Reviewed added backdated utility bill'])->assertOk();$this->getJson('/app-api/finance/closings/'.$id)->assertJsonPath('superseded',true);$this->postJson('/app-api/finance/closing-preview',['campus_id'=>$f['campus'],'bank_account_id'=>null,'closing_date'=>'2026-10-19','opening_balance'=>'99'])->assertJsonPath('opening_balance','3000.00');}
 public function test_pending_closing_rejects_changed_sources_and_bank_scope_does_not_allow_school_wide_partial_reconciliation():void{$f=$this->fixture();$this->login($f);$id=$this->closing($f,'2026-10-18','5000');$this->expense($f,true);$this->postJson('/app-api/finance/closings/'.$id.'/review',['action'=>'approve','reason'=>'Must not approve changed source'])->assertUnprocessable();$this->postJson('/app-api/finance/closings/'.$id.'/review',['action'=>'reject','reason'=>'Backdated transaction changed totals'])->assertOk();$bank=DB::table('bank_accounts')->insertGetId(['school_id'=>$f['sid'],'name'=>'Shared account','opening_balance'=>'0']);$this->postJson('/app-api/finance/closing-preview',['campus_id'=>$f['campus'],'bank_account_id'=>$bank,'closing_date'=>'2026-10-18','opening_balance'=>'0'])->assertUnprocessable();}
 public function test_cash_and_non_cash_accounts_and_foreign_school_categories_are_validated():void{$f=$this->fixture();$b=$this->fixture('B');$this->login($f);$d=$this->data($f);$d['category_id']=$b['category'];$this->postJson('/app-api/finance/expenses',$d)->assertNotFound();$d=$this->data($f);$d['bank_account_id']=$f['bank'];$this->postJson('/app-api/finance/expenses',$d)->assertUnprocessable();$d['method']='bank_transfer';$this->postJson('/app-api/finance/expenses',$d)->assertUnprocessable();$d['reference']='BANK-UTIL-01';$this->postJson('/app-api/finance/expenses',$d)->assertOk();$this->report($b)->assertNotFound();}
 public function test_school_roles_overrides_and_license_guard_financial_access():void{$f=$this->fixture();$this->login($f);$teacher=DB::table('roles')->where('name','teacher')->value('id');DB::table('membership_roles')->where('membership_id',$f['mid'])->update(['role_id'=>$teacher]);$this->getJson('/app-api/finance/setup')->assertForbidden();$accountant=DB::table('roles')->where('name','accountant')->value('id');DB::table('membership_roles')->where('membership_id',$f['mid'])->update(['role_id'=>$accountant]);$this->getJson('/app-api/finance/setup')->assertOk();$id=$this->postJson('/app-api/finance/expenses',$this->data($f))->assertOk()->json('id');$this->postJson('/app-api/finance/expenses/'.$id.'/action',['action'=>'approve','lock_version'=>0,'reason'=>'Accountant cannot approve'])->assertForbidden();foreach(['finance.manage','finance.view'] as $p)DB::table('school_role_permissions')->insert(['school_id'=>$f['sid'],'role_id'=>$accountant,'permission_id'=>DB::table('permissions')->where('name',$p)->value('id'),'enabled'=>false]);$this->seed(\Database\Seeders\FinanceAccessSeeder::class);$this->getJson('/app-api/finance/setup')->assertForbidden();}
 public function test_database_rejects_cross_school_reversal_links():void{$f=$this->fixture();$b=$this->fixture('B');$this->login($b);$id=$this->expense($b,true);$this->expectException(\Illuminate\Database\QueryException::class);DB::table('expense_reversals')->insert(['school_id'=>$f['sid'],'expense_id'=>$id,'kind'=>'refund','amount'=>'1','method'=>'cash','effective_on'=>'2026-10-19','reason'=>'Invalid cross-school link','status'=>'pending','requested_by'=>$f['mid'],'entry_key'=>(string)Str::uuid(),'request_hash'=>str_repeat('a',64)]);}
 public function test_combined_cash_flow_counts_source_payments_once_and_separates_refunds_and_book_corrections():void{$f=$this->fixture();$this->login($f);$sid=$f['sid'];$student=DB::table('students')->insertGetId(['school_id'=>$sid,'admission_no'=>'FIN-1','first_name'=>'Student','admitted_on'=>'2026-10-01','status'=>'active']);$payment=DB::table('payments')->insertGetId(['school_id'=>$sid,'campus_id'=>$f['campus'],'student_id'=>$student,'received_by'=>$f['mid'],'receipt_no'=>'RCT-FIN-1','amount'=>'10000','method'=>'cash','paid_at'=>'2026-10-17 07:00:00','idempotency_key'=>(string)Str::uuid()]);foreach([['refund','1000','2026-10-18 07:00:00'],['correction','500','2026-10-19 07:00:00']] as [$kind,$amount,$at])DB::table('payment_reversals')->insert(['school_id'=>$sid,'payment_id'=>$payment,'kind'=>$kind,'amount'=>$amount,'reason'=>'Reviewed fee '.$kind,'status'=>'approved','approved_by'=>$f['mid'],'reversed_at'=>$at,'idempotency_key'=>(string)Str::uuid(),'refund_method'=>$kind==='refund'?'bank_transfer':null,'refund_bank_account_id'=>$kind==='refund'?$f['bank']:null]);$staff=DB::table('staff_profiles')->insertGetId(['school_id'=>$sid,'membership_id'=>$f['mid'],'employee_no'=>'FIN-STAFF','status'=>'active']);$salary=DB::table('salary_structures')->insertGetId(['school_id'=>$sid,'staff_profile_id'=>$staff,'starts_on'=>'2026-08-01','status'=>'active']);$salaryPayment=DB::table('salary_payments')->insertGetId(['school_id'=>$sid,'campus_id'=>$f['campus'],'staff_profile_id'=>$staff,'amount'=>'2000','paid_at'=>'2026-10-18 07:00:00','method'=>'cash','recorded_by'=>$f['mid'],'idempotency_key'=>(string)Str::uuid()]);foreach(['2026-08-01','2026-09-01'] as $period){$run=DB::table('payroll_runs')->insertGetId(['school_id'=>$sid,'campus_id'=>$f['campus'],'period'=>$period,'revision'=>1,'status'=>'approved']);$item=DB::table('payroll_items')->insertGetId(['school_id'=>$sid,'payroll_run_id'=>$run,'staff_profile_id'=>$staff,'salary_structure_id'=>$salary,'gross_amount'=>'1000','deduction_amount'=>'0','advance_recovery'=>'0','net_amount'=>'1000']);DB::table('salary_payment_allocations')->insert(['school_id'=>$sid,'salary_payment_id'=>$salaryPayment,'payroll_item_id'=>$item,'amount'=>'1000']);}DB::table('salary_payment_reversals')->insert(['school_id'=>$sid,'salary_payment_id'=>$salaryPayment,'amount'=>'2000','reason'=>'Wrong salary bookkeeping','approved_by'=>$f['mid'],'reversed_at'=>'2026-10-19 07:00:00']);DB::table('staff_advances')->insert(['school_id'=>$sid,'staff_profile_id'=>$staff,'campus_id'=>$f['campus'],'amount'=>'3000','monthly_recovery'=>'500','status'=>'void','paid_on'=>'2026-10-18','method'=>'cash','voided_at'=>'2026-10-19 07:00:00','voided_by'=>$f['mid']]);$expense=$this->expense($f,true);$reversal=$this->postJson('/app-api/finance/expenses/'.$expense.'/reversals',['kind'=>'refund','amount'=>'300','method'=>'cash','bank_account_id'=>null,'effective_on'=>'2026-10-19','reason'=>'Returned actual cash from supplier','entry_key'=>(string)Str::uuid()])->assertOk()->json('id');$this->postJson('/app-api/finance/reversals/'.$reversal.'/review',['action'=>'approve','reason'=>'Verified supplier returned cash'])->assertOk();$data=$this->report($f)->assertOk()->assertJsonPath('totals.inflow','10300.00')->assertJsonPath('totals.outflow','7000.00')->assertJsonPath('totals.actual_net','3300.00')->assertJsonPath('totals.corrections','4500.00')->assertJsonPath('totals.book_net','7800.00')->assertJsonPath('totals.accounts.cash','8800.00')->json();$this->assertCount(1,array_filter($data['rows'],fn($r)=>$r['source']==='salary_payment'));$this->assertSame('-1000.00',$data['totals']['accounts']['bank:'.$f['bank']]);$this->report($f,'2026-10-17','2026-10-17')->assertJsonPath('totals.book_net','10000.00');}
 public function test_accountant_cannot_read_another_campus_or_provider_workspace_and_reseed_does_not_grant_approval():void{$f=$this->fixture();$this->login($f);$other=DB::table('campuses')->insertGetId(['school_id'=>$f['sid'],'name'=>'Private campus','code'=>'PRIVATE','status'=>'active']);$accountant=DB::table('roles')->where('name','accountant')->value('id');DB::table('membership_roles')->where('membership_id',$f['mid'])->update(['role_id'=>$accountant]);$this->getJson('/app-api/finance/report?campus_id='.$other.'&from=2026-10-01&to=2026-10-19')->assertNotFound();$this->getJson('/app-api/finance/closings?campus_id='.$other)->assertNotFound();$this->postJson('/app-api/finance/banks',['campus_id'=>$f['campus'],'name'=>'Not an approver'])->assertForbidden();$provider=User::factory()->create();DB::table('platform_admins')->insert(['user_id'=>$provider->id,'active'=>true]);$this->actingAs($provider)->withSession(['school_id'=>$f['sid']])->getJson('/app-api/finance/setup')->assertForbidden();}

}
